                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>15L Milk Per Month</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-purple-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>Custom Schedule</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-purple-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>20% Discount</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-purple-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>Free Delivery + Priority</span>
                  </div>
                </div>

                {/* CTA Button */}
                <div className="p-6 pt-0">
                  <button 
                    onClick={() => handleSubscribe('monthly')}
                    className="w-full py-3 bg-gradient-to-r from-purple-500 to-pink-500 text-white font-semibold rounded-xl hover:from-purple-600 hover:to-pink-600 transform transition-all duration-300 hover:scale-105 shadow-lg"
                  >
                    Start Monthly Plan
                  </button>
                </div>

                {/* Best Value Badge */}
                <div className="absolute top-4 right-4 bg-gradient-to-r from-purple-500 to-pink-500 text-white text-xs font-bold px-3 py-1 rounded-full">
                  BEST VALUE
                </div>
              </div>
            </div>

          </div>

          {/* Additional Benefits */}
          <div className="mt-12 text-center">
            <div className={`inline-flex items-center px-6 py-3 rounded-full ${
              isDarkMode ? 'bg-gray-800/60 border border-gray-700/50' : 'bg-white/60 border border-gray-200/50'
            } backdrop-blur-md shadow-lg`}>
              <svg className="w-5 h-5 text-primary-500 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <span className={`text-sm font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                All plans include: Pause/Resume anytime • No cancellation fees • 24/7 support
              </span>
            </div>
          </div>

        </div>
      </section>

      {/* Subscription Confirmation Modal */}
      {subscriptionModal && selectedPlan && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className={`relative max-w-md w-full rounded-3xl shadow-2xl ${
            isDarkMode ? 'bg-gray-800 border border-gray-700' : 'bg-white border border-gray-200'
          }`}>
            
            {/* Modal Header */}
            <div className="p-6 border-b border-gray-200/20 dark:border-gray-700/20">
              <div className="flex items-center justify-between">
                <h3 className={`text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                  Confirm Subscription
                </h3>
                <button
                  onClick={() => setSubscriptionModal(false)}
                  className={`p-2 rounded-full transition-colors ${
                    isDarkMode ? 'hover:bg-gray-700' : 'hover:bg-gray-100'
                  }`}
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
            </div>

            {/* Modal Body */}
            <div className="p-6">
              {(() => {
                const plan = getPlanDetails(selectedPlan);
                return plan ? (
                  <div className="space-y-4">
                    {/* Plan Summary */}
                    <div className={`p-4 rounded-2xl ${
                      isDarkMode ? 'bg-gray-700/50' : 'bg-gray-50'
                    }`}>
                      <div className="flex items-center justify-between mb-2">
                        <h4 className={`text-xl font-semibold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                          {plan.name}
                        </h4>
                        <div className="text-right">
                          <div className="text-2xl font-bold text-primary-600 dark:text-primary-400">
                            ₹{plan.price}
                          </div>
                          <div className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
                            per {plan.duration}
                          </div>
                        </div>
                      </div>
                      
                      {/* Plan Features */}
                      <div className="space-y-2 mt-4">
                        {plan.features.map((feature, index) => (
                          <div key={index} className="flex items-center">
                            <svg className="w-4 h-4 text-green-500 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                            </svg>
                            <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                              {feature}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>

                    {/* Important Info */}
                    <div className={`p-4 rounded-2xl ${
                      isDarkMode ? 'bg-blue-900/30 border border-blue-800/50' : 'bg-blue-50 border border-blue-200'
                    }`}>
                      <div className="flex items-start">
                        <svg className="w-5 h-5 text-blue-500 mr-3 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                        <div>
                          <h5 className={`font-semibold mb-1 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                            Important Information
                          </h5>
                          <ul className={`text-sm space-y-1 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                            <li>• Subscription starts immediately</li>
                            <li>• You can pause/resume anytime</li>
                            <li>• No cancellation fees</li>
                            <li>• Free delivery included</li>
                          </ul>
                        </div>
                      </div>
                    </div>

                    {/* Payment Info */}
                    <div className={`p-4 rounded-2xl ${
                      isDarkMode ? 'bg-gray-700/50' : 'bg-gray-50'
                    }`}>
                      <div className="flex items-center">
                        <svg className="w-5 h-5 text-yellow-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" />
                        </svg>
                        <div>
                          <h5 className={`font-semibold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                            Payment Method
                          </h5>
                          <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
                            Auto-debit from your registered payment method
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                ) : null;
              })()}
            </div>

            {/* Modal Footer */}
            <div className="p-6 border-t border-gray-200/20 dark:border-gray-700/20">
              <div className="flex gap-3">
                <button
                  onClick={() => setSubscriptionModal(false)}
                  className={`flex-1 py-3 px-4 rounded-xl font-semibold transition-colors ${
                    isDarkMode 
                      ? 'bg-gray-700 hover:bg-gray-600 text-white' 
                      : 'bg-gray-100 hover:bg-gray-200 text-gray-800'
                  }`}
                >
                  Cancel
                </button>
                <button
                  onClick={() => {
                    console.log('Confirm button clicked!');
                    createSubscriptionHandler();
                  }}
                  disabled={loadingSubscription}
                  className="flex-1 py-3 px-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-semibold rounded-xl hover:from-primary-600 hover:to-secondary-600 transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {loadingSubscription ? (
                    <span className="flex items-center justify-center">
                      <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      Processing...
                    </span>
                  ) : (
                    'Confirm Subscription'
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* QR Code Payment Modal */}
      {qrCodeModal && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-lg flex items-center justify-center z-[9999] p-4"
          onContextMenu={(e) => e.preventDefault()}
        >
          {console.log('QR Code Modal rendering, qrCodeModal:', qrCodeModal, 'qrCodeData exists:', !!qrCodeData)}
          {/* Glass background effect */}
          <div className="absolute inset-0 bg-gradient-to-br from-blue-500/10 via-purple-500/10 to-pink-500/10 backdrop-blur-sm"></div>
          
          <div 
            className="relative bg-white/95 backdrop-blur-xl rounded-2xl p-6 max-w-md w-full mx-auto shadow-2xl border border-white/20 max-h-[90vh] overflow-y-auto scrollbar-hide"
            onContextMenu={(e) => e.preventDefault()}
          >
            <style>{`
              .scrollbar-hide::-webkit-scrollbar {
                display: none;
              }
              .scrollbar-hide {
                -ms-overflow-style: none;
                scrollbar-width: none;
              }
            `}</style>
            
            {/* Modal Header - Compact */}
            <div className="text-center mb-4">
              <div className="w-12 h-12 mx-auto mb-2 bg-gradient-to-br from-blue-500 to-purple-600 rounded-xl flex items-center justify-center shadow-lg">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                </svg>
              </div>
              <h2 className="text-xl font-bold text-gray-900">Complete Subscription Payment</h2>
              <p className="text-gray-500 text-sm">Subscription #{subscriptionId?.slice(-8)?.toUpperCase()}</p>
            </div>

            {/* Amount - Compact */}
            <div className="text-center mb-4">
              <div className="text-4xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
                ₹{getPlanDetails(selectedPlan)?.price || 0}
              </div>
            </div>

            {/* QR Code - Smaller with glow */}
            <div className="flex justify-center mb-4">
              <div className="relative">
                <div className="absolute inset-0 bg-gradient-to-r from-blue-400 to-purple-400 rounded-2xl blur-lg opacity-30"></div>
                <div className="relative bg-white p-3 rounded-2xl border border-gray-200 shadow-lg">
                  {qrCodeData ? (
                    <img 
                      src={qrCodeData} 
                      alt="Payment QR Code" 
                      className="w-40 h-40"
                    />
                  ) : (
                    <div className="w-40 h-40 flex items-center justify-center">
                      <svg className="w-16 h-16 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M12 21l-1-1m0-4v.01M12 17l4-4m4 4h.01M5 19H4" />
                      </svg>
                    </div>
                  )}
                </div>
              </div>
            </div>}

            {/* UPI ID - Compact */}
            <div className="bg-gray-50 rounded-xl p-3 mb-3">
              <div className="text-xs text-gray-600 mb-2 text-center font-medium">Or pay to UPI ID</div>
              <div className="flex items-center gap-2">
                <code className="flex-1 bg-white px-3 py-2 rounded-lg text-sm font-mono text-gray-800 border border-gray-200 text-center">
                  amrutanshu20003-16@oksbi
                </code>
                <button
                  onClick={() => {
                    navigator.clipboard.writeText('amrutanshu20003-16@oksbi');
                    alert('UPI ID copied to clipboard!');
                  }}
                  className="px-3 py-2 rounded-lg text-sm font-medium bg-blue-500 text-white hover:bg-blue-600 transition-colors"
                >
                  Copy
                </button>
              </div>
            </div>

            {/* Instructions - Compact */}
            <div className="bg-gradient-to-br from-blue-50 to-purple-50 rounded-xl p-3 mb-3">
              <div className="flex items-center gap-2 mb-2">
                <div className="w-6 h-6 bg-blue-500 rounded-md flex items-center justify-center">
                  <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                  </svg>
                </div>
                <span className="font-semibold text-gray-800 text-sm">How to Pay</span>
              </div>
              <ol className="text-xs text-gray-700 space-y-1">
                <li className="flex items-start gap-1.5">
                  <span className="w-4 h-4 bg-blue-500 text-white rounded-full flex items-center justify-center text-[10px] flex-shrink-0 mt-0.5">1</span>
                  <span>Open UPI app</span>
                </li>
                <li className="flex items-start gap-1.5">
                  <span className="w-4 h-4 bg-blue-500 text-white rounded-full flex items-center justify-center text-[10px] flex-shrink-0 mt-0.5">2</span>
                  <span>Scan QR or enter ID</span>
                </li>
                <li className="flex items-start gap-1.5">
                  <span className="w-4 h-4 bg-blue-500 text-white rounded-full flex items-center justify-center text-[10px] flex-shrink-0 mt-0.5">3</span>
                  <span>Pay ₹{getPlanDetails(selectedPlan)?.price || 0}</span>
                </li>
                <li className="flex items-start gap-1.5">
                  <span className="w-4 h-4 bg-blue-500 text-white rounded-full flex items-center justify-center text-[10px] flex-shrink-0 mt-0.5">4</span>
                  <span>Wait for verification</span>
                </li>
              </ol>
            </div>

            {/* Waiting Message - Compact */}
            <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-3">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-yellow-500 rounded-full flex items-center justify-center flex-shrink-0">
                  <svg className="w-4 h-4 text-white animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path>
                  </svg>
                </div>
                <div>
                  <div className="font-semibold text-yellow-800 text-sm">Please Do Not Close</div>
                  <div className="text-xs text-yellow-700">Auto-closes after verification</div>
                </div>
              </div>
            </div>

            {/* Modal Footer */}
            <div className="flex gap-3 mt-4">
              <button
                onClick={() => setQrCodeModal(false)}
                className="flex-1 py-3 px-4 bg-gray-100 hover:bg-gray-200 text-gray-800 font-semibold rounded-xl transition-colors"
              >
                Close
              </button>
              <button
                onClick={() => {
                  if (subscriptionId) {
                    navigator.clipboard.writeText(subscriptionId);
                    alert('Subscription ID copied to clipboard!');
                  }
                }}
                className="flex-1 py-3 px-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-semibold rounded-xl hover:from-primary-600 hover:to-secondary-600 transition-all duration-300"
              >
                Copy ID
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Toast Container */}

      {toasts.map(toast => (

        <Toast

          key={toast.id}

          message={toast.message}

          type={toast.type}

          duration={toast.duration}

          onClose={() => removeToast(toast.id)}

        />

      ))}

    </div>

  );

};



export default Home;
